 setShapeSettings();
 }
 public Shape(String name) {
 this.name = name;
 setShapeSettings();
 }
 public void setShapeSettings() {
 filled = false;
 fillColour = null;
 lineColour = Color.BLACK;
 }
 public boolean isFilled() {
 return filled;
 }
 public void setFilled(boolean filled) {
 this.filled = filled;
 }
 public Color getFillColour() {
 return fillColour;
